          "question": "Public comment at special municipal meetings; alleged retaliation through attorney-disciplinary complaints; taxpayer challenge to outside counsel.",
          "holding": "Affirmed dismissal with prejudice. An agenda-germaneness rule at special meetings satisfied reasonableness and viewpoint-neutrality requirements under the Illinois Constitution; regular meetings allowed other topics. Retaliation claims failed pleading requirements. The outside-counsel claim failed for taxpayer standing and, alternatively, lawful appointment/ratification.",
