          "judgeRole": "Joined the majority judgment",
          "topic": "Individualized findings before pretrial detention",
          "question": "Whether a detention petition was timely and whether the trial court explained why release conditions could not mitigate danger.",
          "holding": "The petition was timely, but the detention order was vacated and the case remanded for a prompt new detention hearing because the trial court's findings were insufficient for meaningful appellate review.",
          "reasoning": "Serious charges and dangerousness alone do not resolve whether conditions can mitigate risk. The trial court had not explained why proposed relocation, monitoring, supervision or no-contact restrictions were inadequate; prior failure to pay fines did not supply that explanation.",
          "subsequentHistory": "Vacated and remanded, 2–1 The post-remand hearing and later case-specific appellate history were not verified. Later Morgan (2025) supplies the current general standard-of-review framework. Later legal context: 2025 IL 130626: Detention decisions and supporting factual findings receive manifest-weight review where live witness testimony was presented. Where the hearing proceeds solely through proffers and documentary evidence, the reviewing court independently reviews that evidence de novo. Later controlling standard-of-review guidance, not a subsequent appeal in Woods or Post. Knecht did not sit on this Supreme Court decision.",
          "precedentialStatus": "Rule 23 nonprecedential order, subject to the exceptions stated in the order",
          "limitations": "Procedural adequacy of detention findings; the panel did not acquit the accused or order unconditional release. The prosecution could present evidence at the new hearing. The dissent considered the existing findings sufficient and the appellate claim forfeited.",
