          "trialActionDate": null,
          "court": "Illinois Appellate Court, Fourth District",
          "judgeRole": "Joined the opinion and judgment",
          "topic": "Second Amendment and substantive due process",
          "question": "Permanent surrender of firearms and FOID card following a felony conviction; constitutionality of an identity-theft provision.",
          "holding": "Upheld the firearm-surrender order following a felony stalking conviction, rejecting facial and as-applied Second Amendment challenges. Separately struck the identity-theft provision and vacated that conviction, while otherwise affirming.",
          "reasoning": "Following Fourth District precedent, the panel treated convicted felons, including nonviolent felons, as outside the protection it attributed to law-abiding citizens. It read Rahimi as not deciding categorical felony disarmament. Applying the Illinois Supreme Court's Madrigal precedent and accepting the State's concession, it found the identity-theft clause irrationally criminalized innocent information searches.",
          "subsequentHistory": "Affirmed in part and vacated in part, unanimous No later case-specific appellate disposition verified. Do not claim a complete current-law treatment or that all felony-disarmament questions are settled nationally.",
          "precedentialStatus": "Published opinion; official-reports PDF dated May 12, 2025, rather than the earlier Rule 23 version",
          "limitations": "Gun-surrender and identity-theft issues were constitutional merits rulings. The separate felon-in-possession criminal statute, section 24-1.1, was not reviewed on its merits because the defendant lacked standing to challenge an offense with which she was not charged.",
