          "court": "Illinois Appellate Court, Fifth District",
          "judgeRole": "Author of unanimous judgment and opinion",
          "topic": "Gun rights and armed violence",
          "question": "Constitutional merits of this statutory challenge. Not an assault-weapons-ban case, a general license requirement, or a ruling on every firearm possession by a nonviolent offender.",
          "holding": "Affirmed the armed-violence conviction and rejected both facial and as-applied Second Amendment challenges to a law covering possession of cocaine while carrying an operational firearm.",
          "reasoning": "The opinion concluded that a person simultaneously committing a felony and carrying an operational gun was outside the Amendment's protected class. Alternatively, it found historical support for the restriction, including analogies to disarming felons and temporary restrictions involving intoxicants.",
          "subsequentHistory": "Affirmed the Jefferson County judgment, including the 18-year sentence. Illinois Supreme Court denied leave to appeal on January 28, 2026, Supreme Court docket 132483 (identifying appellate docket 5-23-0656). This is a denial of discretionary review, not a merits affirmance. Any later federal review was not verified. Later legal context: A later U.S. Supreme Court decision rejected an automatic federal gun ban applied solely because of regular marijuana use. Hemani did not decide Smith's Illinois cocaine-possession armed-violence question, and no subsequent decision applying Hemani to Smith was verified. Hemani also expressly reserved convicted-felon restrictions and several other drug-related firearm questions.",
          "precedentialStatus": "Final in official opinion index as retrieved November 1, 2026",
          "limitations": "Constitutional merits of this statutory challenge. Not an assault-weapons-ban case, a general license requirement, or a ruling on every firearm possession by a nonviolent offender.",
