          "topic": "Pretrial detention eligibility",
          "question": "Statutory eligibility ruling in an interlocutory detention appeal. It did not decide whether Illinois should use cash bail or whether the SAFE-T Act is constitutional.",
          "holding": "Reversed an order releasing a defendant and required a new hearing because aggravated battery by strangulation can qualify for detention under the statute's residual clause when the actual conduct threatens or inflicts great bodily harm.",
          "reasoning": "The court declined another district's narrower construction and read the residual clause to focus on conduct. It distinguished a charge of strangulation from a charge expressly requiring actual great bodily harm; eligibility was conditional on the facts, not automatic for every strangulation charge.",
