          "topic": "Workers' compensation benefits and credit for prior payments",
          "question": "",
          "holding": "Ruth confirmed the Commission's award of permanent-partial-disability benefits and its denial of the employer's requested credit for earlier voluntary payments for the same injury.",
          "reasoning": "Ruth adopted the Commission’s reading that compensation under section 8(e) should not affect the section 8(d)(2) award. He added that any ambiguity should be resolved through liberal interpretation of the Act to protect injured workers financially; the appellate special concurrence reproduces this rationale.",
