          "precedentialStatus": "",
          "limitations": "The appellate court reviewed the Commission’s legal interpretation and reversed the offset ruling. The special concurrence quotes Ruth’s rationale, but its own analysis is not his. One selected case is not a record-wide labor or business policy measure.",
