          "court": "Illinois Appellate Court, Fourth District, and Illinois Supreme Court, reviewing Champaign County Circuit Court",
          "judgeRole": "Trial judge, Jason M. Bohm; not a member of either reviewing court.",
          "topic": "Local executive authority and appointments to elected-office vacancies",
          "question": "",
          "holding": "Bohm granted summary judgment to the county executive, holding that she had power to fill vacancies in elected county offices, including county-board seats.",
          "reasoning": "He read the County Executive Law's appointment language and governmental structure as transferring the appointment function to the county executive. He did not prohibit the board from using the title of chair.",
          "subsequentHistory": "The Fourth District reversed in 2021. On November 28, 2022, the Illinois Supreme Court unanimously affirmed that reversal: the Election Code assigns those elected-office appointments to the county-board chair; the executive's general appointment statute did not override it.",
