          "subsequentHistory": "The Fourth District affirmed on April 25, 2024. It found the individualized record sufficient, but identified an erroneous form checkbox describing prior violent behavior and held that error harmless. Later People v. Morgan (2025 IL 130626, paragraph 54) supplied a different general appellate-review framework: manifest-weight review when live testimony was presented, and independent de novo review when the hearing used only proffers and documents. Morgan was not a subsequent appeal in Woods and does not establish that this case was reversed.",
          "precedentialStatus": "Opinion Official document status: Final. A publication status of Final does not establish that all judicial review is exhausted.",
          "limitations": "An individual detention decision under the Pretrial Fairness Act does not decide whether cash bail should exist. Further proceedings beyond the retrieved decision are not independently certified.",
