          "reasoning": "She read the FOIA exemption's plural wording about names and people as not specifically covering an applicant seeking only his own information. She also concluded an earlier injunction did not bar disclosure to that applicant.",
          "subsequentHistory": "The appellate court initially affirmed in 2022. After the Illinois Supreme Court directed reconsideration in light of Hart v. Illinois State Police, 2023 IL 128275, the appellate court vacated its earlier judgment, reversed Lorton's judgment and remanded on March 19, 2024. It held the FOIA exemption prohibited this disclosure without an exception for the applicant's own records. The appellate court also vacated the attorney-fee and cost award, and noted that the applicant could seek the information through the Firearms Services Bureau instead of FOIA.",
