          "citation": "2024 IL App (3d) 240003-U",
          "date": "2024-05-31",
          "dateMeaning": "Reviewing decision date",
          "trialActionDate": "2023-06-07",
          "court": "Illinois Appellate Court, Third District, reviewing DuPage County Circuit Court",
          "judgeRole": "Original trial judge who entered the parenting allocation judgment; a different judge, Maureen Riordan, handled later posttrial motions",
          "topic": "Parenting time, shared decision-making, and child support",
          "question": "",
          "holding": "Felice awarded joint parental decision-making and equal parenting time, designating the mother's residence for school purposes. He set child support with retroactivity only to January 2021.",
          "reasoning": "He applied statutory best-interest factors, finding a history of shared care and decision-making, relationships with both parents, and a workable equal schedule.",
          "subsequentHistory": "The 2024 appellate order affirmed the parenting allocation and left other issues unresolved for lack of jurisdiction. Review was denied August 22, 2024. In the later 2026 appeal from Riordan's posttrial rulings, the court required support retroactive to March 10, 2020, subject to payment credits. It also reversed separate contempt and name-change rulings by Riordan; those were not Felice's decisions.",
          "precedentialStatus": "",
          "limitations": "The 2024 decision is a Rule 23 order. Later posttrial decisions must not be attributed to Felice. This illustrates individualized application of family law, not general political ideology.",
