          "dateMeaning": "date of reviewing decision",
          "trialActionDate": null,
          "court": "Illinois Appellate Court, First District",
          "judgeRole": "Circuit judge in the postconviction and certificate-of-innocence proceedings; this entry does not attribute the 1998 trial rulings or appellate decision to her.",
          "topic": "Actual innocence and access to a certificate of innocence",
          "question": "",
          "holding": "Hansen vacated Drew's murder conviction and granted a new trial after an evidentiary hearing on newly discovered evidence. After the State dismissed the charges, she declined to grant a certificate of innocence under section 5-5-4(c), then certified the legal question for interlocutory review.",
          "reasoning": "She found a recanting witness's evidence new, material and sufficiently conclusive to probably change a retrial, but reasoned that she had not affirmatively determined Drew innocent for a certificate.",
          "subsequentHistory": "The First District answered the modified certified question in the affirmative and remanded: a certificate is mandatory when the specified statutory requirements are met, without an additional affirmative innocence finding. This was a certified-question decision, not review of the 1998 conviction. Further proceedings were not verified.",
          "precedentialStatus": "Published opinion Official document status: Released. A publication status of Final does not establish that all judicial review is exhausted.",
          "limitations": "The appellate index lists the opinion as Released. Its procedural posture and the judge's earlier grant of postconviction relief must accompany the certificate ruling.",
