          "question": "",
          "holding": "Denied DCFS employees' motion to dismiss a wrongful-death suit on sovereign-immunity grounds and certified the legal question for immediate appellate review.",
          "reasoning": "Dempsey reasoned that the employees' Child Welfare Employee Licenses imposed a professional standard of care independent of state employment, relying on Griffin v. Poynter.",
          "subsequentHistory": "The appellate court rejected that reasoning, answered the certified question in the employees' favor, and remanded for dismissal: investigating child abuse was a uniquely governmental function, and the employment-specific license did not create an independent duty outside state service.",
