          "holding": "Granted summary judgment to Menards in a bicyclist's injury suit involving a pipe that came loose from a customer's truck; the claim against the driver remained pending.",
          "reasoning": "No transcript of the summary-judgment hearing was in the appellate record, so the opinion does not supply Dempsey's detailed oral reasoning. The appellate court independently concluded that helping load a pipe did not amount to undertaking to secure it; the customer secured it himself and did not rely on the store to do so.",
