          "dateMeaning": "Appellate decision filing date",
          "trialActionDate": null,
          "court": "Illinois Appellate Court, First District",
          "judgeRole": "Circuit-court trial judge whose ruling is described in the appellate decision; not an appellate panel member",
          "topic": "Tenant remedies; attorney fees",
          "question": "",
          "holding": "Awarded a tenant damages on two landlord-tenant ordinance claims but limited attorney fees to work before the landlord's January 2019 payment offer, awarding $3,369 in fees.",
          "reasoning": "Dickler treated delivery of a $4,000 check as a valid legal tender that cut off further recoverable fees, and treated a later check as an attempt to correct that tender.",
          "subsequentHistory": "Reversed and remanded for a new fee-and-cost determination. The appellate court held that neither payment was a valid tender: the first was a conditional settlement offer that did not provide all requested relief; the later payment omitted reasonable fees/costs and did not concede all relevant liability.",
          "precedentialStatus": "Rule 23 Official document status: Slip. A publication status of Final does not establish that all judicial review is exhausted.",
          "limitations": "The reversal concerns attorney fees, not a reversal of every merits ruling in the landlord-tenant dispute. Rule 23 order. Further docket history after remand was not comprehensively checked.",
