          "reasoning": "She found the investigation related to the divorce litigation and was protected by absolute litigation privilege. She also found the driver-record disclosure fell within the statute’s permitted litigation use.",
          "subsequentHistory": "The appellate court affirmed. It agreed on litigation privilege for the privacy torts and permitted statutory use for the driver-record claim; it did not decide whether the privilege independently defeats that statutory claim. The injunction claim was affirmed because the plaintiff forfeited the issue by failing to argue the required elements or cite supporting authority.",
