          "question": "",
          "holding": "Quinn’s February 26, 2025 order retained existing parenting time, limited each parent to a five-minute call during the other’s parenting time, and provided a $1,000 fine for the mother’s police wellness-check calls unless the father was arrested.",
          "reasoning": "The order treated the father’s modification motion as an emergency and referred to an earlier restriction on police calls about parenting issues. The appellate record lacked hearing transcripts, limiting verification of the full rationale.",
          "subsequentHistory": "The appellate court dismissed for lack of jurisdiction: unresolved matters lacked a Rule 304(a) finding, and the attempted appeal also missed the 14-day route for permissive custody appeals. It did not decide whether the restrictions were correct.",
